// Keyset (cursor) pagination for the users list. The cursor is opaque to
// clients: a base64url JSON tuple carrying the sort, the order, the sort key of
// the last row and its id. Decoding checks that it belongs to the same sort and
// order, so a cursor cannot be replayed against a differently ordered query.
//
// Sort keys: `createdAt` orders by the primary key, a UUIDv7 generated by
// PostgreSQL at insert time (time-ordered at millisecond precision and unique),
// which keeps the predicate exact — `created_at` itself has microsecond
// precision that a JavaScript Date cannot carry across pages. `fullName` orders
// by (full_name, id) with the id as tie-breaker.
import { usersError } from './users.errors.js';

export const USER_SORT_FIELDS = ['createdAt', 'fullName'] as const;
export type UserSortField = (typeof USER_SORT_FIELDS)[number];

export const SORT_ORDERS = ['asc', 'desc'] as const;
export type SortOrder = (typeof SORT_ORDERS)[number];

export interface UserCursor {
  sort: UserSortField;
  order: SortOrder;
  /** Sort key of the last row of the previous page; null for `createdAt` (the id is the key). */
  key: string | null;
  /** Id of the last row of the previous page. */
  id: string;
}

const CURSOR_VERSION = 1;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function encodeUserCursor(cursor: UserCursor): string {
  const tuple = [CURSOR_VERSION, cursor.sort, cursor.order, cursor.key, cursor.id];
  return Buffer.from(JSON.stringify(tuple), 'utf8').toString('base64url');
}

/** Decodes a cursor for the given sort and order; throws `cursor_invalid` (400) otherwise. */
export function decodeUserCursor(raw: string, sort: UserSortField, order: SortOrder): UserCursor {
  let parsed: unknown;
  try {
    parsed = JSON.parse(Buffer.from(raw, 'base64url').toString('utf8'));
  } catch {
    throw usersError.cursorInvalid();
  }
  if (!Array.isArray(parsed) || parsed.length !== 5) throw usersError.cursorInvalid();
  const [version, cursorSort, cursorOrder, key, id] = parsed as unknown[];
  if (version !== CURSOR_VERSION || cursorSort !== sort || cursorOrder !== order) {
    throw usersError.cursorInvalid();
  }
  if (typeof id !== 'string' || !UUID.test(id)) throw usersError.cursorInvalid();
  if (sort === 'createdAt' ? key !== null : typeof key !== 'string') throw usersError.cursorInvalid();
  return { sort, order, key: key as string | null, id };
}
